题意：要求查询(u,v)之间路径点权第K小
考虑如何用加减法构造出只包含u-&gt;v路径点的权值线段树
我们可以考虑以根作为前缀，建立从根至叶子结点的主席树。
很容易知道(u,v)路径点的权值线段树&#x3D;&#x3D;sum[u]+sum[v]-sum[ lca(u,v)]-sum[ fa[ lca(u,v) ] ];
(我不会告诉你我一开始眼瞎看成了边权第K小然后看这个式子怎么看都和别人的不一样)
inline int read()&#123;    int x=0,f=1;char ch = getchar();    while(&#x27;0&#x27;&gt;ch||ch&gt;&#x27;9&#x27;)&#123;if(&#x27;-&#x27;==ch)f=-1;ch=getchar();&#125;    while(&#x27;0&#x27;&lt;=ch&amp;&amp;ch&lt;=&#x27;9&#x27;)&#123;x=(x&lt;&lt;3)+(x&lt;&lt;1)+ch-&#x27;0&#x27;;ch=getchar();&#125;    return x*f;&#125;using namespace std;const int N=100000+10;//head endint n,m,w[N],b[N];struct node&#123;    int to,next;&#125;G[N&lt;&lt;1];int head[N],tot;// chairTree beginconst int MN=100000+10;int rt[MN],ls[MN*20],rs[MN*20],sum[MN*20],chairtree,siz;void build(int &amp;rt,int l,int r)&#123;    rt=++chairtree;    sum[rt]=0;    if(l&gt;=r)return ;    int m =((r-l)&gt;&gt;1)+l;    build(ls[rt],l,m);    build(rs[rt],m+1,r);&#125;void update(int&amp; rt,int l,int r,int last,int pos)&#123;    rt=++chairtree;    ls[rt]=ls[last];    rs[rt]=rs[last];    sum[rt]=sum[last]+1;    if(l&gt;=r) return ;    int m=((r-l)&gt;&gt;1)+l;    if(pos&lt;=m) update(ls[rt],l  ,m,ls[last],pos);    else       update(rs[rt],m+1,r,rs[last],pos);&#125;int query(int rt,int l,int r,int last,int lca,int flca,int k)&#123;    if(l&gt;=r) return l;    int m=((r-l)&gt;&gt;1)+l;    int cnt=sum[ls[rt]]+sum[ls[last]]-sum[ls[lca]]-sum[ls[flca]];    if(k&lt;=cnt) query(ls[rt],l  ,m,ls[last],ls[lca],ls[flca],k);    else       query(rs[rt],m+1,r,rs[last],rs[lca],rs[flca],k-cnt);&#125;void dfs(int rt,int l,int r)&#123;    int m = ((r-l)&gt;&gt;1)+l;    printf(&quot;%d&quot;,sum[rt]);    if(l&gt;=r) return ;printf(&quot;( &quot;);    dfs(ls[rt],l,m);printf(&quot;_%*d,&quot;,2,ls[rt]);    dfs(rs[rt],m+1,r);printf(&quot;_%*d )&quot;,2,rs[rt]);&#125;//chairTree endvoid add(int u,int v)&#123;    G[++tot].to=v,G[tot].next=head[u],head[u]=tot;    G[++tot].to=u,G[tot].next=head[v],head[v]=tot;&#125;int dep[N],fa[N],sz[N],son[N];void dfs1(int u,int f,int d)&#123;    dep[u]=d,fa[u]=f,sz[u]=1,son[u]=0;    for(int i=head[u],to;i;i=G[i].next)&#123;        to=G[i].to;        if(to==f)continue;        dfs1(to,u,d+1);        sz[u]+=sz[to];        if(sz[son[u]]&lt;sz[to])son[u]=to;    &#125;&#125;int tree[N],top[N],pre[N],cnt;void dfs2(int u,int tp)&#123;    top[u]=tp,tree[u]=++cnt,pre[tree[u]]=u;    update(rt[u],1,siz,rt[fa[u]],w[u]);    if(!son[u])return;    dfs2(son[u],tp);    for(int i=head[u],to;i;i=G[i].next)&#123;        to=G[i].to;        if(to==fa[u]||to==son[u])continue;        dfs2(to,to);    &#125;&#125;int Lca(int x,int y)&#123;    int fx=top[x],fy=top[y];    while(fx!=fy)&#123;        if(dep[fx]&lt;dep[fy])swap(x,y),swap(fx,fy);        x=fa[fx],fx=top[x];    &#125;    if(dep[x]&gt;dep[y])swap(x,y);    return x;&#125;int main()&#123;    #ifndef ONLINE_JUDGE    freopen(&quot;D:\\GitHub\\ACM-ICPC\\other\\in.txt&quot;,&quot;r&quot;,stdin);    #endif    n=read(),m=read();    for(int i=1;i&lt;=n;i++) w[i]=read(),b[i]=w[i];    for(int i=1;i&lt; n;i++) add(read(),read());    fa[1]=0;    sort(b+1,b+n+1);    siz = unique(b+1,b+n+1)-(b+1);    for(int i=1;i&lt;=n;i++) w[i]=lower_bound(b+1,b+siz+1,w[i])-b;    build(rt[0],1,siz);    //dfs(rt[0],1,siz);    dfs1(1,0,1),dfs2(1,1);    while(m--)&#123;        int u,v,k;        u=read(),v=read(),k=read();        int lca=Lca(u,v);        printf(&quot;%d\n&quot;,(b[query(rt[u],1,siz,rt[v],rt[lca],rt[fa[lca]],k)]));    &#125;    #ifndef ONLINE_JUDGE    printf(&quot;My Time:%.3lfms\n&quot;,(double)clock()/CLOCKS_PER_SEC);    #endif&#125;
